def compare_versions(a: str, b: str) -> int:
    def parse(v):
        v = v.split('+', 1)[0]
        if '-' in v:
            core, pre = v.split('-', 1)
            pre_ids = pre.split('.')
        else:
            core, pre_ids = v, []
        major, minor, patch = (int(x) for x in core.split('.'))
        return (major, minor, patch), pre_ids

    def cmp(x, y):
        return (x > y) - (x < y)

    def compare_ident(x, y):
        xd, yd = x.isdigit(), y.isdigit()
        if xd and yd:
            return cmp(int(x), int(y))
        if xd:
            return -1
        if yd:
            return 1
        return cmp(x, y)

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    c = cmp(core_a, core_b)
    if c != 0:
        return c

    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1

    for x, y in zip(pre_a, pre_b):
        c = compare_ident(x, y)
        if c != 0:
            return c

    return cmp(len(pre_a), len(pre_b))
